import type { EnvObject, Process } from "./types.ts";

const _envShim = Object.create(null);

const _getEnv = (useShim?: boolean): EnvObject =>
  globalThis.process?.env ||
  (import.meta as unknown as { env: EnvObject }).env ||
  (globalThis as unknown as { Deno: { env: { toObject: () => EnvObject } } })
    .Deno?.env.toObject() ||
  (globalThis as unknown as { __env__: EnvObject }).__env__ ||
  (useShim ? _envShim : globalThis);

/**
 * A proxy to the current environment variables.
 */
export const env: EnvObject = new Proxy(_envShim, {
  get(_, prop) {
    const env = _getEnv();
    return env[prop as any] ?? _envShim[prop];
  },
  has(_, prop) {
    const env = _getEnv();
    return prop in env || prop in _envShim;
  },
  set(_, prop, value) {
    const env = _getEnv(true);
    env[prop as any] = value;
    return true;
  },
  deleteProperty(_, prop) {
    if (!prop) {
      return false;
    }
    const env = _getEnv(true);
    delete env[prop as any];
    return true;
  },
  ownKeys() {
    const env = _getEnv(true);
    return Object.keys(env);
  },
});

/**
 * A proxy to the `process` object.
 */
export const process: Process = new Proxy(
  globalThis.process || { env },
  {} as any,
);

/**
 * Value of the current `NODE_ENV` environment variable (if set).
 */
export const nodeENV: string =
  (typeof process !== "undefined" && process.env && process.env.NODE_ENV) || "";

import { env, nodeENV, process } from "./env.ts";
import { provider } from "./providers.ts";
import { toBoolean } from "./_utils.ts";

/** Value of the process.platform */
export const platform = process.platform || "";

/** Detect if `CI` environment variable is set or a provider CI detected */
export const isCI = toBoolean(env.CI) || Boolean(provider);

/** Detect if stdout.TTY is available */
export const hasTTY = toBoolean(process.stdout && process.stdout.isTTY);

/** Detect if global `window` object is available */
export const hasWindow = typeof window !== "undefined";

/** Detect if `DEBUG` environment variable is set */
export const isDebug = toBoolean(env.DEBUG);

/** Detect if `NODE_ENV` environment variable is `test` */
export const isTest = nodeENV === "test" || toBoolean(env.TEST);

/** Detect if `NODE_ENV` environment variable is `production` */
export const isProduction = nodeENV === "production";

/** Detect if `NODE_ENV` environment variable is `development` */
export const isDevelopment = nodeENV === "development" || nodeENV === "dev";

/** Detect if MINIMAL environment variable is set, running in CI or test or TTY is unavailable */
export const isMinimal = toBoolean(env.MINIMAL) || isCI || isTest || !hasTTY;

/** Detect if process.platform is Windows */
export const isWindows = /^win/i.test(platform);

/** Detect if process.platform is Linux */
export const isLinux = /^linux/i.test(platform);

/** Detect if process.platform is macOS (darwin kernel) */
export const isMacOS = /^darwin/i.test(platform);

/** Color Support */
export const isColorSupported =
  !toBoolean(env.NO_COLOR) &&
  (toBoolean(env.FORCE_COLOR) ||
    ((hasTTY || isWindows) && env.TERM !== "dumb") ||
    isCI);

/** Value of the NODE_ENV environment variable (or sensitive fallback to MODE) */
export const mode = nodeENV || env.MODE;

