import { createEnv } from "@t3-oss/env-core";
import { z } from "zod";

export const env = createEnv({
  server: {
    PORT: z.string(),
  },

  /**
   * The prefix that client-side variables must have. This is enforced both at
   * a type-level and at runtime.
   */
  clientPrefix: "PUBLIC_",

  client: {
    PUBLIC_API_URL: z.string(),
  },

  /**
   * What object holds the environment variables at runtime. This is usually
   * `process.env` or `import.meta.env`.
   */
  runtimeEnv: import.meta.env,

  /**
   * By default, this library will feed the environment variables directly to
   * the Zod validator.
   *
   * This means that if you have an empty string for a value that is supposed
   * to be a number (e.g. `PORT=` in a `.env` file), Zod will incorrectly flag
   * it as a type mismatch violation.
   *
   * By setting this option to `true`, we tell the library to treat empty
   * strings as `undefined`.
   */
  emptyStringAsUndefined: true,

  /**
   * Run `build` or `dev` with `SKIP_ENV_VALIDATION` to skip env validation.
   * This is especially useful for Docker builds.
   */
  skipValidation: import.meta.env.SKIP_ENV_VALIDATION === "development",
});

import { env } from "./t3-env";

export function Counter() {
  console.log(" initializing counter on the client", env.PUBLIC_API_URL);
  return <div>Client API Url:{env.PUBLIC_API_URL}</div>;
}

