import * as z from 'zod';
import 'dotenv/config';

const createEnv = () => {
  const EnvSchema = z.object({
    API_URL: z.string(),
    ENABLE_API_MOCKING: z
      .string()
      .refine((s) => s === 'true' || s === 'false')
      .transform((s) => s === 'true')
      .optional(),
    APP_URL: z.string().optional().default('http://localhost:3000'),
    APP_MOCK_API_PORT: z.string().optional().default('8080'),
  });

  const envVars = {
    API_URL: process.env.NEXT_PUBLIC_API_URL,
    ENABLE_API_MOCKING: process.env.NEXT_PUBLIC_ENABLE_API_MOCKING,
    APP_URL: process.env.NEXT_PUBLIC_URL,
    APP_MOCK_API_PORT: process.env.NEXT_PUBLIC_MOCK_API_PORT,
  };

  const parsedEnv = EnvSchema.safeParse(envVars);

  if (!parsedEnv.success) {
    throw new Error(
      `Invalid env provided.
  The following variables are missing or invalid:
  ${Object.entries(parsedEnv.error.flatten().fieldErrors)
    .map(([k, v]) => `- ${k}: ${v}`)
    .join('\n')}
  `,
    );
  }

  return parsedEnv.data ?? {};
};

export const env = createEnv();

/**
 * This file is included in `/next.config.ts` which ensures the app isn't built with invalid env vars.
 * It has to be a `.js`-file to be imported there.
 */

import { z } from 'zod';

const envSchema = z.object({
  DATABASE_URL: z.string().url(),
  NODE_ENV: z.enum(['development', 'test', 'production']),
});

const _env = envSchema.safeParse(process.env);

if (!_env.success) {
  throw new Error(
    '❌ Invalid environment variables: ' +
      JSON.stringify(_env.error.format(), null, 4),
  );
}
export const env = _env.data;

// @ts-check
const { z } = require('zod');

/**
 * @param {Record<string, string | undefined>} input
 */
function parseEnv(input) {
  const envSchema = z.object({
    VERCEL_URL: z
      .string()
      .default('localhost:3000')
      .transform((url) => (!url.startsWith('http') ? `https://${url}` : url))
      .transform((url) => (url.endsWith('/') ? url.slice(0, -1) : url)),
    VERCEL_ENV: z
      .enum(['production', 'building', 'development', 'preview'])
      .default('development'),
    VERCEL_GIT_COMMIT_REF: z.string().default('none'),
    TYPEDOC: z
      .string()
      .default('true')
      .transform((v) => v === 'true'),
  });

  const env = envSchema.parse(input);

  return {
    ...env,
    OG_URL: `${env.VERCEL_URL}/api/og`,
  };
}

module.exports = {
  parseEnv,
};

//Imports for canonical usage:
// const envalid = require('envalid')

const envalid = require('../')

// Validate our env takes what it needs before we start the server:
module.exports = envalid.cleanEnv(process.env, {
  HOST: envalid.host({ default: '127.0.0.1' }),
  PORT: envalid.port({ default: 3000, desc: 'The port to start the server on' }),
  MESSAGE: envalid.str({ default: 'Hello, world' }),
})
